INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(66695, 'deDE', 'Das Schicksal herausfordern: Mausoleum der Ersten', '', '', '', '', '', '', '', '', 45114),
(66694, 'deDE', 'Das Schicksal herausfordern: Sanktum der Herrschaft', '', '', '', '', '', '', '', '', 45114),
(66661, 'deDE', 'Das ist nur eine Münze, was soll die wert sein?', 'Wendet Euch an einen Mittler in Oribos, um mehr zu erfahren.', '<Dieser kuriose Gegenstand bietet mehr Fragen als Antworten. Wie seid Ihr in den Besitz dieses Gegenstands gekommen? Wofür wird er verwendet? Ist er gefährlich?>\n\n<Wenn die Ewige Stadt keine Antworten für Euch bereithält, dann sicherlich die Mittler, die dort ihren Geschäften nachgehen.>', '', '', '', '', '', '', 45114),
(66649, 'deDE', 'Das Blatt wenden', 'Besiegt $1oa verschiedene Bosse schicksalhafter Schlachtzüge.', '<Im Laufe der vielen Prüfungen spürt Ihr, wie die Kraft in Euch wächst. Was auch immer die Quelle dieser Anomalien ist, sie ersetzen Eure Verwirrung immer mehr durch Sicherheit.>\n\n<Taucht noch einmal in die Ungewissheit ein, kämpft gegen die Dunkelheit und ergreift das Schicksal mit beiden Händen.>', '', '', '', '', '', '', 45114),
(66648, 'deDE', 'Jenseits des Schicksals', 'Besiegt 30 verschiedene Bosse schicksalhafter Schlachtzüge.', '<Die Realität dreht sich um Euch. Eure Erinnerungen an diesen Ort verschwimmen und verschieben sich mit jedem Augenblick mehr. Irgendetwas hat sich verändert.>\n\n<Ihr seid Euch sicher, dass dies trotz aller Ähnlichkeiten nicht der Ort ist, den Ihr einst kanntet. Nicht ganz.>\n\n<Aber dennoch ruft der vor Euch liegende Weg. Weder Täuschung noch Verzerrung werden Euer Schicksal aufhalten.>', '', '', '', '', '', '', 45114),
(66619, 'deDE', 'Antros', '', '', '', '', '', '', '', '', 45114),
(66618, 'deDE', 'Mor\'geth', '', '', '', '', '', '', '', '', 45114),
(65411, 'deDE', 'Rätselhafte Situation', '', '', '', '', '', '', '', '', 45114),
(62307, 'deDE', 'Runde 3', '', '', '', '', '', '', '', '', 45114),
(62305, 'deDE', 'Runde 2', '', '', '', '', '', '', '', '', 45114),
(62304, 'deDE', 'Runde 1', '', '', '', '', '', '', '', '', 45114),
(54391, 'deDE', 'Spenden für die Dunkelküste: Spiegelnder Goldberyll', 'Sammelt $1oa gewürzte Lenden für Senedras im Hafen von Boralus.', 'Gutes, herzhaftes Fleisch ist genau die Nahrung, die unsere Verbündeten verdienen, bevor sie in die Schlacht ziehen. Außerdem lässt sich damit ein zünftiger Eintopf zubereiten, genau wie ihn unsere Truppen lieben, wenn die Winde gut stehen und die Nächte kälter werden.\n\nWenn Ihr mir ein paar frische gewürzte Lenden besorgt, bringe ich sie gerne zu unseren Versorgungsoffizieren.', '', '', '', '', '', '', 45114),
(54381, 'deDE', 'Spenden für die Dunkelküste: Ultramarinblaue Tinte', 'Sammelt $1oa Stücke gegrillten Wels für Senedras im Hafen von Boralus.', 'Seid gegrüßt, $gReisender:Reisende;.\n\nMan hat mich gebeten, dafür zu sorgen, dass unsere Nahrungsmittelvorräte nie zur Neige gehen, aber in letzter Zeit wird der Fisch knapp. Habt Ihr etwas, was Ihr gern spenden würdet?', '', '', '', '', '', '', 45114),
(54048, 'deDE', 'Wer die Wächterin stört', 'Besiegt Sira Mondhüter.', '<Das bedrückende Gefühl, dass Ihr verfolgt werdet, ist unerträglich geworden.\n\nIhr wisst, dass jemand hinter Euch ist.>', '', 'Sira hat Euch über die gesamte Dunkelküste gejagt. Sie ist gekommen, um es zu beenden.', 'Sira Mondhüter', '', '', '', 45114),
(53317, 'deDE', 'Verdichtetes Sturmsilber', '', '', '', '', '', '', '', '', 45114),
(52438, 'deDE', 'Ein Höllenritt', 'Schließt Euch der Schlacht bei den Wildschnellen an.', 'Dieses Ding ist eins meiner besten Stücke, das könnt Ihr mir glauben, $gKleiner:Kleine;!\n\nJetzt, wo es mit dem neuesten Spielzeug aufgerüstet ist, dürfen wir keine Zeit verlieren.\n\nDer Kampf tobt an den Wildschnellen. Fliegt in meinem modifizierten Maschinchen in die Schlacht und macht ihnen die Hölle heiß!', '', '', '', '', '', '', 45114),
(52437, 'deDE', 'Der Beginn von etwas Gutem', 'Folgt Sylvanas nach Nazj\'vel.', 'Während der Rest unserer Armee das Lager errichtet, solltet Ihr mir folgen. Auf meiner Rückkehr von Zoram\'gar habe ich etwas... Interessantes... entdeckt.\n\nIch gebe zu, nicht einmal ich hätte einen solch glücklichen Zufall erwartet.\n\nFolgt mir, $n. Und nehmt eine Spitzhacke mit.', '', '', '', '', '', '', 45114),
(50800, 'deDE', 'In die Wälder', 'Schlagt den Hinterhalt der Allianz zurück.', 'Vorsicht, $n. Im Wald wimmelt es noch immer vor Sturmgrimms Truppen...\n\nPasst auf, was hinter Euch passiert!', '', '', '', '', '', '', 45114),
(50772, 'deDE', 'Jagdbefehl', 'Findet Kriegshäuptling Sylvanas Windläufer an der Dunkelküste.', 'Habt Ihr all diese Irrwische bemerkt? Ich habe so etwas schon einmal gesehen, als der Dämon Archimonde von den Stichen Hunderter oder vielmehr Tausender Irrwische gefällt wurde.\n\nDas kann nur eines bedeuten: Malfurion bittet um die Hilfe seiner Ahnen.\n\nDer Kriegshäuptling ist bereits mit einem Spähtrupp zur Dunkelküste geeilt, um ihn abzufangen. Bitte, $n... Findet den Kriegshäuptling und stellt fest, ob sie ihre Beute schon erlegt hat.\n\nWir haben das Eschental schon komplett gesichert, aber wir dürfen jetzt nicht nachlassen.', '', '', '', '', '', '', 45114),
(50738, 'deDE', 'Ankunft zur rechten Zeit', 'Empfangt Kriegshäuptling Sylvanas Windläufer in Astranaar.', 'Meinen Teil der Abmachung habe ich erfüllt, $R.\n\nIch werde mir die anderen Außenposten ansehen und herausfinden, ob meine Brüder und Schwestern zurechtkommen. Trefft Euch mit dem Kriegshäuptling und sagt ihr, dass wir Astranaar gesichert haben. Wenn alles nach Plan verlaufen ist, sollte sie bereits auf dem Weg sein.\n\nOh, und versucht mir ein wenig des Ruhms zukommen zu lassen, ja? \n\n<Lorash grinst Euch an.>', '', '', '', '', '', '', 45114),
